-- 只读不可变旧云档案，原资源表不再含单端云字段；当前回执另行捕获。
SELECT COALESCE(CASE WHEN JSON_TYPE(JSON_EXTRACT(retired.old_values,'$.cloud_backend'))='NULL' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(retired.old_values,'$.cloud_backend')) END,''),COALESCE(CASE WHEN JSON_TYPE(JSON_EXTRACT(retired.old_values,'$.cloud_path'))='NULL' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(retired.old_values,'$.cloud_path')) END,''),COALESCE(CASE WHEN JSON_TYPE(JSON_EXTRACT(retired.old_values,'$.cloud_checksum'))='NULL' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(retired.old_values,'$.cloud_checksum')) END,''),CAST(COALESCE(CASE WHEN JSON_TYPE(JSON_EXTRACT(retired.old_values,'$.cloud_size_bytes'))='NULL' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(retired.old_values,'$.cloud_size_bytes')) END,0) AS UNSIGNED),retired.content_generation,retired.source_identity
FROM album_resources r JOIN resource_cloud_migration_audit retired ON retired.run_id='schema-retirement-v2026102913' AND retired.owner_type='album' AND retired.resource_id=r.id AND retired.disposition='archived'
WHERE r.id=? FOR UPDATE
